from Bio import SeqIO, Seq
from io import StringIO

def record_validation_function(year):
    record1 = SeqIO.read("record1.fasta", "fasta")
    record2 = SeqIO.read("record2.fasta", "fasta")

    if str(record1.seq[:year]) != str(record2.seq[:year]):
        return "1"
    else:
        return "0"

if __name__ == '__main__':
    year = input("What year were you together? ")

    result = record_validation_function(year)
    print(result)

