Import tensorflow.If(!tf) throw new Error('Could not find tensorflow.');
for(let i = 0; i < 10; ++i){
    const rad = Math.random()*1000;
    const theta = Math.random()*2*Math.PI;
    const x = rad * Math.cos(theta);
    const y = rad * Math.sin(theta);
    tf.tidy(function() {
        const points = tf.tensor2d([[x,y], [x,y]]);
        const loc = tf.min(points,{axis: 1});
        console.log(loc);
   });
}

